/**
 * The automation's Preflight check configuration. On update the whole
 * group is replaced; ``enabled`` alone may be omitted to keep its state.
 */
export interface AutomationScriptCheckRequest {
  /** Whether the script gates the automation's runs. Omitted keeps the current state; a new configuration starts enabled. */
  enabled?: boolean | null;
  /** Script runtime. One of: python, node, bash. */
  runtime: string;
  /** Org secrets exposed to the script as environment variables. Requires the manage-org-secrets permission whenever non-empty. */
  secret_names?: string[];
  /**
     * The script source (at most 256KB). It reads the trigger event from $EVENT_FILE, may read/write a small JSON object at $STATE_FILE that persists across runs, and must write its decision to $OUTPUT_FILE: {"run": true}, {"run": false, "reason": "..."}, or {"items": [...]} (one action run per item).
     * @minLength 1
     */
  source: string;
  /**
     * Wall-clock limit for one run; a run past it fails closed (no actions start).
     * @minimum 1
     * @maximum 300
     */
  timeout_seconds?: number;
}

