/**
 * notify_thread: dispatch-time one-way 'session started' breadcrumb in the triggering thread (Slack triggers). attach_thread: dispatch-time two-way binding to the triggering thread (Slack triggers). post_response: deliver the agent's response to the triggering context.
 */
export type AutomationReplyType = typeof AutomationReplyType[keyof typeof AutomationReplyType];


export const AutomationReplyType = {
  notify_thread: 'notify_thread',
  attach_thread: 'attach_thread',
  post_response: 'post_response',
} as const;

export interface AutomationReply {
  /** notify_thread: dispatch-time one-way 'session started' breadcrumb in the triggering thread (Slack triggers). attach_thread: dispatch-time two-way binding to the triggering thread (Slack triggers). post_response: deliver the agent's response to the triggering context. */
  type: AutomationReplyType;
}

export interface AutomationTriggerRequestInput {
  /** null matches every event, except Slack message triggers require a channel restriction or at least one completed filter in every group. is_thread_reply alone does not satisfy this requirement. */
  conditions?: AutomationConditionsInput | null;
  /** Trigger event type, e.g. 'github:pull_request'. */
  event_type: AutomationTriggerRequestInputEventType;
  /** Where this trigger's session binds and its response is delivered. Only the matched trigger's replies execute, all entries independently; entries are deduplicated. */
  replies?: AutomationReply[];
}

export interface AutomationCreateRequest {
  /** Non-empty. Caps: at most one start_session; monitor_session must be the only action. */
  actions: (AutomationStartSessionActionInput | AutomationMessageSessionAction | AutomationMonitorSessionAction)[];
  concurrency?: AutomationConcurrency | null;
  enabled?: boolean;
  limits?: AutomationLimits | null;
  /** Optional LLM check: a fast model that decides per trigger event whether the automation runs. */
  llm_check?: AutomationLlmCheckRequest | null;
  /** Org-visible key/value labels for organizing/filtering automations. At most 16 pairs; keys at most 32 chars; values at most 128. */
  metadata?: AutomationCreateRequestMetadata;
  /**
     * @minLength 1
     * @maxLength 500
     */
  name: string;
  notifications?: AutomationNotifications | null;
  /** Required: explicitly choose the identity spawned sessions run under (organization, creator, or service_user). */
  run_as: AutomationRunAsOrganization | AutomationRunAsCreator | AutomationRunAsServiceUser;
  /** Optional script Preflight check: a script that runs before the actions and decides per trigger whether to proceed, skip, or fan out. Validated and written with the automation. */
  script_check?: AutomationScriptCheckRequest | null;
  /** The automation's own security-profile binding; omitted = inherit from the org/enterprise. Requires the security-profile management permission. */
  security_profile?: AutomationSecurityProfileSelection | null;
  /** Applied to sessions this automation spawns. */
  session_settings?: AutomationSessionSettingsInput | null;
  /** Who may reply into existing sessions from Slack threads: devin_users (linked Devin accounts only), slack_users (anyone in the organization's connected Slack workspaces), or external_slack_users (also Slack Connect users). Does not affect who can trigger the automation. */
  slack_reply_access?: AutomationCreateRequestSlackReplyAccess;
  /** Who may reply into existing sessions from Microsoft Teams threads: devin_users (linked Devin accounts only) or teams_users (anyone in the organization's connected Microsoft tenant; the default). Does not affect who can trigger the automation. */
  teams_reply_access?: AutomationCreateRequestTeamsReplyAccess;
  /** Create-only provenance marker; resolve ids via the templates endpoint. When set and tools.mcp_servers is omitted, the template's required_mcps apply. */
  template_id?: string | null;
  tools?: AutomationTools | null;
  /** Fires when any trigger matches; once per event. At most one webhook:incoming trigger. */
  triggers: AutomationTriggerRequestInput[];
}

