/**
 * PATCH fields merge member-wise by default: omitted members are kept,
 * explicit nulls clear, and empty groups are no-ops. Metadata merges per key,
 * with null values deleting keys. Lists replace wholesale (deletion = resend
 * the list without the element), while each sent element merges onto the
 * stored element of the same type when that type occurs exactly once on both
 * sides. Element members that are required on create (``prompt``,
 * ``setup_prompt``, the monitor/triage slack configs, ``scan_id``) may be
 * omitted when a counterpart exists — they carry like any other member;
 * explicit null is rejected.
 */
export interface AutomationUpdateRequest {
  actions?: (AutomationStartSessionActionUpdate | AutomationMessageSessionActionUpdate | AutomationMonitorSessionActionUpdate)[] | null;
  concurrency?: AutomationConcurrency | null;
  enabled?: boolean | null;
  limits?: AutomationLimits | null;
  /** Replace the automation's LLM check (filter prompt and enabled state). Omitted keeps the current one; null is rejected, disable it with enabled=false instead. */
  llm_check?: AutomationLlmCheckRequest;
  metadata?: AutomationUpdateRequestMetadata;
  name?: string | null;
  notifications?: AutomationNotifications | null;
  /** null resets to organization. */
  run_as?: AutomationRunAsOrganization | AutomationRunAsCreator | AutomationRunAsServiceUser | null;
  /** Replace the automation's script Preflight check (script, runtime, timeout, secrets, enabled state). Omitted keeps the current one; null is rejected, disable it with enabled=false instead. */
  script_check?: AutomationScriptCheckRequest;
  /** The automation's own security-profile binding: a profile_id pins that profile, {"profile_id": null} records an explicit opt-out, and explicit null reverts to inheriting from the org/enterprise. Requires the security-profile management permission. */
  security_profile?: AutomationSecurityProfileSelection | null;
  session_settings?: AutomationSessionSettingsInput | null;
  /** null resets to slack_users. */
  slack_reply_access?: AutomationUpdateRequestSlackReplyAccess;
  /** null resets to teams_users. */
  teams_reply_access?: AutomationUpdateRequestTeamsReplyAccess;
  tools?: AutomationTools | null;
  triggers?: AutomationTriggerRequestInput[] | null;
}

